cd "d:/Antigravity/The-Bliss-at-Home/the-bliss-at-home" && python3 -c "
import re

with open('docs/project-timeline.html', 'r', encoding='utf-8') as f:
    content = f.read()

# Extract DATA section
start = content.index('__TASK_DATA_START__')
end = content.index('__TASK_DATA_END__')
data_section = content[start:end]

# Find all sections with their IDs and tasks
sections = re.findall(r\"id:'(\w+)'.*?tasks:\[(.*?)\]\}\", data_section, re.DOTALL)

for sid, tasks_str in sections:
    pcts = [int(x) for x in re.findall(r'pct:(\d+)', tasks_str)]
    avg = round(sum(pcts) / len(pcts)) if pcts else 0
    print(f'{sid}: {avg}% ({len(pcts)} tasks, sum={sum(pcts)})')
" 2>/dev/null || node -e "
const fs = require('fs');
const content = fs.readFileSync('docs/project-timeline.html', 'utf8');
const start = content.indexOf('__TASK_DATA_START__');
const end = content.indexOf('__TASK_DATA_END__');
const dataSection = content.substring(start, end);
const sectionRegex = /id:'(\w+)'.*?tasks:\[(.*?)\]\}/gs;
let m;
while ((m = sectionRegex.exec(dataSection)) !== null) {
    const sid = m[1];
    const pcts = [...m[2].matchAll(/pct:(\d+)/g)].map(x => parseInt(x[1]));
    const avg = pcts.length ? Math.round(pcts.reduce((a,b)=>a+b,0) / pcts.length) : 0;
    console.log(sid + ': ' + avg + '% (' + pcts.length + ' tasks, sum=' + pcts.reduce((a,b)=>a+b,0) + ')');
}
"

