// Agent timeout settings
const AGENT_TIMEOUT_MS = 30 * 60 * 1000;  // 30 minutes - mark as timeout
const AGENT_CLEANUP_MS = 60 * 60 * 1000;  // 60 minutes - remove from list

// Check and update agent timeouts
function checkAgentTimeouts() {
  const now = Date.now();
  let changed = false;

  for (const [id, agent] of agents.entries()) {
    // Main agents now also get timeout/cleanup (removed skip logic)
    const lastSeen = agent.lastSeen ? new Date(agent.lastSeen).getTime() : 0;
    const elapsed = now - lastSeen;

    // Mark active agents as timeout if no activity for 30 min
    if (agent.status === 'active' && elapsed > AGENT_TIMEOUT_MS) {
      agents.set(id, {
        ...agent,
        status: 'timeout',
        timeoutAt: new Date().toISOString()
      });
      console.log(`[AGENT] Agent ${id} marked as timeout (${Math.round(elapsed / 60000)} min inactive)`);
      changed = true;
    }

    // Remove old stopped/timeout agents after 60 min
